CREATE OR REPLACE FUNCTION public.same_approval_scope(_officer uuid,_section uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.phase2_admin() OR public.has_any_role(auth.uid(),ARRAY['hr_officer']::public.app_role[]) OR EXISTS(SELECT 1 FROM public.officers actor LEFT JOIN public.officers target ON target.id=_officer WHERE actor.user_id=auth.uid() AND ((public.has_any_role(auth.uid(),ARRAY['section_head']::public.app_role[]) AND actor.section_id=coalesce(_section,target.section_id)) OR (public.has_any_role(auth.uid(),ARRAY['assistant_commissioner','dc_admin','dc_academy']::public.app_role[]) AND actor.office_id=coalesce(target.office_id,(SELECT office_id FROM public.sections WHERE id=_section))))) $$;
CREATE OR REPLACE FUNCTION public.guard_approval_scope() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NEW.history<>OLD.history THEN IF TG_TABLE_NAME='leave_requests' THEN IF NOT public.same_approval_scope((to_jsonb(NEW)->>'officer_id')::uuid,NULL) THEN RAISE EXCEPTION 'This leave request is outside your assigned section or division'; END IF; ELSIF TG_TABLE_NAME='erp_documents' AND OLD.status='Pending' THEN IF NOT public.same_approval_scope(NULL,(to_jsonb(NEW)->>'section_id')::uuid) THEN RAISE EXCEPTION 'This document is outside your assigned section or division'; END IF; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_leave_approval_scope BEFORE UPDATE ON public.leave_requests FOR EACH ROW EXECUTE FUNCTION public.guard_approval_scope(); CREATE TRIGGER guard_document_approval_scope BEFORE UPDATE ON public.erp_documents FOR EACH ROW EXECUTE FUNCTION public.guard_approval_scope();
CREATE OR REPLACE FUNCTION public.guard_registry_assignment() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.officer_id IS NOT NULL AND NEW.officer_id IS DISTINCT FROM OLD.officer_id AND NOT EXISTS(SELECT 1 FROM public.officers WHERE id=NEW.officer_id AND office_id=NEW.office_id) THEN RAISE EXCEPTION 'Choose an officer in the assigned office'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_registry_assignment BEFORE UPDATE ON public.correspondence FOR EACH ROW EXECUTE FUNCTION public.guard_registry_assignment();